{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In CD1 mice, PRE-084 was rapidly distributed to the CNS with a brain concentration at Tmax of 773.6 ng/g and a plasma concentration of 651.5 ng/mL, demonstrating meaningful brain exposure after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Norcyclizine in rats showed a brain AUC to plasma AUC ratio possibly greater than 2, indicating brain exposure exceeding plasma exposure after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[11C]ketamine showed relatively poor brain uptake in animal studies, but this was attributed to rapid metabolism rather than intrinsic blood-brain barrier impermeability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most direct in-vivo analog evidence supports rapid and meaningful CNS access after systemic administration, with brain/CSF concentrations comparable to or exceeding plasma. The single negative record is confounded by rapid metabolism, so the overall prediction is pass.",
  "evidence_gaps": [
    "No direct query-specific CNS exposure data are available; evidence is transferred from analogs with Morgan similarities at or below 0.34.",
    "The negative ketamine record is confounded by rapid metabolism and may not reflect intrinsic BBB permeability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

